export const initialLayout={Up:'c',Down:'d',Left:'e',Right:'f',X:'g',Y:'h',A:'j',B:'i',L:'k',R:'l',Select:'m',Start:'n'};
export const actions=[['Show answer / Play or pause',{key_code:'spacebar'}],['Again',{key_code:'1'}],['Hard',{key_code:'2'}],['Good',{key_code:'3'}],['Easy',{key_code:'4'}],['Undo',{key_code:'z',modifiers:['left_command']}],['Bury card',{key_code:'hyphen'}],['Suspend note',{key_code:'2',modifiers:['left_shift']}],['Scroll up',{mouse_key:{vertical_wheel:-32}}],['Scroll down',{mouse_key:{vertical_wheel:32}}]];
export function findRule(state,key,mode){return state.rule.manipulators.find(m=>m.from?.key_code===key&&m.conditions?.some(c=>c.type==='variable_if'&&c.name==='8bitdo_mode'&&c.value===mode));}
export function label(to){if(!to)return 'Pass through';if(to.length!==1)return 'Custom sequence';if(to[0].set_variable)return 'Switch mode';const a=actions.find(a=>JSON.stringify(a[1])===JSON.stringify(to[0]));if(a)return a[0];return (to[0].modifiers||[]).map(m=>({left_command:'⌘',left_shift:'⇧',left_option:'⌥',left_control:'⌃'}[m]||m)).join('')+(to[0].key_code||'Custom action');}
export function outputKey(to){if(!to)return '—';const t=to[0];return t.key_code|| (t.set_variable?'⇄':t.mouse_key?'↕':'…');}
export function assign(state,button,key){const old=state.layout[button];if(Object.entries(state.layout).some(([b,k])=>b!==button&&k===key))throw Error('That key is assigned to another button. Capture a different key first.');for(const m of state.rule.manipulators){if(m.from?.key_code===old)m.from.key_code=key;}state.layout[button]=key;}
export function setOutput(state,key,mode,to){let m=findRule(state,key,mode);if(!to){state.rule.manipulators=state.rule.manipulators.filter(x=>x!==m);return;}if(m){m.to=to;return;}state.rule.manipulators.push({type:'basic',from:{key_code:key},to,conditions:[{type:'device_if',identifiers:[{vendor_id:state.vendor,product_id:state.product}]},{type:'variable_if',name:'8bitdo_mode',value:mode}]});}
export function exportConfig(state){const rule=structuredClone(state.rule);delete rule.enabled;rule.description='Clickshift: 8BitDo Video / Anki';for(const m of rule.manipulators){for(const c of m.conditions||[]){if(c.type==='device_if')c.identifiers=[{vendor_id:state.vendor,product_id:state.product}];}}return {title:'Clickshift · 8BitDo',rules:[rule]};}
export function parseImport(data){const rule=data.rules?.[0]||data;if(!Array.isArray(rule.manipulators)||!rule.manipulators.length)throw Error('Choose a Karabiner rule or a file with a rules array.');if(data.rules?.length>1)throw Error('Import one rule at a time to avoid dropping additional rules.');if(!rule.manipulators.every(m=>m.type==='basic'&&m.from?.key_code&&Array.isArray(m.to)&&m.conditions?.some(c=>c.type==='variable_if'&&c.name==='8bitdo_mode'&&[0,1].includes(c.value))))throw Error('This editor supports keyboard rules using 8bitdo_mode 0 and 1, like the supplied example.');const device=rule.manipulators.flatMap(m=>m.conditions||[]).find(c=>c.type==='device_if')?.identifiers?.[0];if(!device||!Number.isInteger(device.vendor_id)||!Number.isInteger(device.product_id))throw Error('The rule needs numeric vendor and product IDs.');const layout={...initialLayout};const known=new Set(Object.values(layout));let i=1;for(const m of rule.manipulators)if(!known.has(m.from.key_code)){layout['Extra '+i++]=m.from.key_code;known.add(m.from.key_code);}return {rule:structuredClone(rule),layout,vendor:device.vendor_id,product:device.product_id};}
export function eventKey(e){if(/^Key[A-Z]$/.test(e.code))return e.code.slice(3).toLowerCase();if(/^Digit\d$/.test(e.code))return e.code.slice(5);if(/^F\d+$/.test(e.code))return e.code.toLowerCase();return {Space:'spacebar',Enter:'return_or_enter',Escape:'escape',Tab:'tab',Backspace:'delete_or_backspace',Delete:'delete_forward',ArrowUp:'up_arrow',ArrowDown:'down_arrow',ArrowLeft:'left_arrow',ArrowRight:'right_arrow',Minus:'hyphen',Equal:'equal_sign',BracketLeft:'open_bracket',BracketRight:'close_bracket',Backslash:'backslash',Semicolon:'semicolon',Quote:'quote',Comma:'comma',Period:'period',Slash:'slash',Backquote:'grave_accent_and_tilde'}[e.code]||null;}
